module ControlFsm (
	clk,
	rst_n,
	r_dec,
	r_level,
	i_valid,
	i_ready,
	o_ready,
	o_valid,
	c_stateen,
	c_srow0,
	c_srow1,
	c_srow2,
	c_isrow0,
	c_isrow1,
	c_mixcol,
	c_loadkey,
	c_keyen,
	c_ke0,
	c_ke1,
	c_ke2,
	c_kxor,
	c_ikxor,
	c_dec192_keysel,
	c_add,
	c_sbox
);
	reg _sv2v_0;
	input wire clk;
	input wire rst_n;
	input wire r_dec;
	input wire [1:0] r_level;
	input wire i_valid;
	output wire i_ready;
	input wire o_ready;
	output wire o_valid;
	output wire c_stateen;
	output wire c_srow0;
	output wire c_srow1;
	output wire c_srow2;
	output wire c_isrow0;
	output wire c_isrow1;
	output wire c_mixcol;
	output wire c_loadkey;
	output wire c_keyen;
	output wire c_ke0;
	output wire c_ke1;
	output wire c_ke2;
	output wire c_kxor;
	output wire [4:0] c_ikxor;
	output wire [1:0] c_dec192_keysel;
	output wire c_add;
	output wire c_sbox;
	localparam [351:0] kE128InitLut = 352';
	localparam [505:0] kE128RoundLut = 506';
	localparam [439:0] kE128FinalLut = 440';
	localparam [439:0] kD128InitLut = 440';
	localparam [681:0] kD128RoundLut = 682';
	localparam [351:0] kD128FinalLut = 352';
	localparam [505:0] kE192InitLut = 506';
	localparam [439:0] kE192R1Lut = 440';
	localparam [505:0] kE192R2Lut = 506';
	localparam [505:0] kE192R3Lut = 506';
	localparam [593:0] kE192R4Lut = 594';
	localparam [439:0] kE192FinalLut = 440';
	localparam [593:0] kD192InitLut = 594';
	localparam [769:0] kD192R1Lut = 770';
	localparam [681:0] kD192R2Lut = 682';
	localparam [681:0] kD192R3Lut = 682';
	localparam [351:0] kD192FinalLut = 352';
	localparam [1143:0] kE256InitLut = 1144';
	localparam [505:0] kE256R1Lut = 506';
	localparam [505:0] kE256R3Lut = 506';
	localparam [505:0] kE256R4Lut = 506';
	localparam [439:0] kE256FinalLut = 440';
	localparam [769:0] kD256InitLut = 770';
	localparam [681:0] kD256R1Lut = 682';
	localparam [681:0] kD256R2Lut = 682';
	localparam [351:0] kD256FinalLut = 352';
	reg [4:0] state;
	reg [4:0] state_n;
	reg [5:0] cycle_q;
	reg [3:0] round_q;
	reg dec_q;
	reg [1:0] level_q;
	reg [21:0] ctrl;
	function automatic [5:0] key_cycles;
		input reg [1:0] level;
		case (level)
			2'b00: key_cycles = 16;
			2'b01: key_cycles = 24;
			default: key_cycles = 32;
		endcase
	endfunction
	function automatic [5:0] cycles;
		input reg [4:0] s;
		case (s)
			5'd2, 5'd7, 5'd18, 5'd27: cycles = 16;
			5'd3, 5'd10, 5'd11, 5'd20, 5'd21, 5'd22, 5'd8: cycles = 23;
			5'd4, 5'd5, 5'd9, 5'd13, 5'd23: cycles = 20;
			5'd6, 5'd16, 5'd17, 5'd25, 5'd26: cycles = 31;
			5'd12, 5'd14: cycles = 27;
			5'd15, 5'd24: cycles = 35;
			5'd19: cycles = 52;
			default: cycles = 1;
		endcase
	endfunction
	function automatic is_round;
		input reg [4:0] s;
		case (s)
			5'd3, 5'd6, 5'd9, 5'd10, 5'd11, 5'd12, 5'd15, 5'd16, 5'd17, 5'd20, 5'd21, 5'd22, 5'd25, 5'd26: is_round = 1'b1;
			default: is_round = 1'b0;
		endcase
	endfunction
	function automatic [21:0] lut;
		input reg [4:0] s;
		input reg [5:0] i;
		begin
			lut = 1'sb0;
			case (s)
				5'd2: lut = kE128InitLut[(15 - i) * 22+:22];
				5'd3: lut = kE128RoundLut[(22 - i) * 22+:22];
				5'd4: lut = kE128FinalLut[(19 - i) * 22+:22];
				5'd5: lut = kD128InitLut[(19 - i) * 22+:22];
				5'd6: lut = kD128RoundLut[(30 - i) * 22+:22];
				5'd7: lut = kD128FinalLut[(15 - i) * 22+:22];
				5'd8: lut = kE192InitLut[(22 - i) * 22+:22];
				5'd9: lut = kE192R1Lut[(19 - i) * 22+:22];
				5'd10: lut = kE192R2Lut[(22 - i) * 22+:22];
				5'd11: lut = kE192R3Lut[(22 - i) * 22+:22];
				5'd12: lut = kE192R4Lut[(26 - i) * 22+:22];
				5'd13: lut = kE192FinalLut[(19 - i) * 22+:22];
				5'd14: lut = kD192InitLut[(26 - i) * 22+:22];
				5'd15: lut = kD192R1Lut[(34 - i) * 22+:22];
				5'd16: lut = kD192R2Lut[(30 - i) * 22+:22];
				5'd17: lut = kD192R3Lut[(30 - i) * 22+:22];
				5'd18: lut = kD192FinalLut[(15 - i) * 22+:22];
				5'd19: lut = kE256InitLut[(51 - i) * 22+:22];
				5'd20: lut = kE256R1Lut[(22 - i) * 22+:22];
				5'd21: lut = kE256R3Lut[(22 - i) * 22+:22];
				5'd22: lut = kE256R4Lut[(22 - i) * 22+:22];
				5'd23: lut = kE256FinalLut[(19 - i) * 22+:22];
				5'd24: lut = kD256InitLut[(34 - i) * 22+:22];
				5'd25: lut = kD256R1Lut[(30 - i) * 22+:22];
				5'd26: lut = kD256R2Lut[(30 - i) * 22+:22];
				5'd27: lut = kD256FinalLut[(15 - i) * 22+:22];
				default:
					;
			endcase
		end
	endfunction
	always @(*) begin
		if (_sv2v_0)
			;
		state_n = state;
		case (state)
			5'd0:
				if (i_valid && (cycle_q == 15))
					state_n = 5'd1;
			5'd1:
				if (i_valid && (cycle_q == (key_cycles(level_q) - 1)))
					case ({dec_q, level_q})
						3'b000: state_n = 5'd2;
						3'b001: state_n = 5'd8;
						3'b010, 3'b011: state_n = 5'd19;
						3'b100: state_n = 5'd5;
						3'b101: state_n = 5'd14;
						default: state_n = 5'd24;
					endcase
			5'd2: state_n = 5'd3;
			5'd3:
				if (round_q == 8)
					state_n = 5'd4;
			5'd4: state_n = 5'd28;
			5'd5: state_n = 5'd6;
			5'd6:
				if (round_q == 8)
					state_n = 5'd7;
			5'd7: state_n = 5'd28;
			5'd8: state_n = 5'd9;
			5'd9: state_n = 5'd10;
			5'd10: state_n = (round_q == 10 ? 5'd13 : 5'd11);
			5'd11: state_n = 5'd12;
			5'd12: state_n = 5'd10;
			5'd13: state_n = 5'd28;
			5'd14: state_n = 5'd15;
			5'd15: state_n = 5'd16;
			5'd16: state_n = (round_q == 10 ? 5'd18 : 5'd17);
			5'd17: state_n = 5'd15;
			5'd18: state_n = 5'd28;
			5'd19: state_n = 5'd20;
			5'd20:
				if (round_q == 1)
					state_n = 5'd21;
			5'd21: state_n = (round_q == 12 ? 5'd23 : 5'd22);
			5'd22: state_n = 5'd21;
			5'd23: state_n = 5'd28;
			5'd24: state_n = 5'd25;
			5'd25: state_n = (round_q == 12 ? 5'd27 : 5'd26);
			5'd26: state_n = 5'd25;
			5'd27: state_n = 5'd28;
			5'd28:
				if (o_ready && (cycle_q == 15))
					state_n = 5'd0;
			default: state_n = 5'd0;
		endcase
	end
	always @(posedge clk or negedge rst_n)
		if (!rst_n) begin
			state <= 5'd0;
			cycle_q <= 1'sb0;
			round_q <= 1'sb0;
			dec_q <= 0;
			level_q <= 0;
		end
		else if (((state == 5'd0) || (state == 5'd1)) && !i_valid)
			;
		else if ((state == 5'd28) && !o_ready)
			;
		else begin
			if ((state == 5'd0) && (cycle_q == 0)) begin
				dec_q <= r_dec;
				level_q <= r_level;
			end
			if (((((state == 5'd0) && (cycle_q == 15)) || ((state == 5'd1) && (cycle_q == (key_cycles(level_q) - 1)))) || ((state == 5'd28) && (cycle_q == 15))) || ((((state != 5'd0) && (state != 5'd1)) && (state != 5'd28)) && (cycle_q == (cycles(state) - 1)))) begin
				state <= state_n;
				cycle_q <= 1'sb0;
				if (is_round(state))
					round_q <= round_q + 1'b1;
				else if (state == 5'd1)
					round_q <= 1'sb0;
			end
			else
				cycle_q <= cycle_q + 1'b1;
		end
	always @(*) begin
		if (_sv2v_0)
			;
		ctrl = lut(state, cycle_q);
		if (state == 5'd0)
			ctrl[21] = i_valid;
		if (state == 5'd1) begin
			ctrl[13] = i_valid;
			ctrl[14] = i_valid;
		end
		if (state == 5'd28)
			ctrl[21] = o_ready;
	end
	assign i_ready = (state == 5'd0) || (state == 5'd1);
	assign o_valid = state == 5'd28;
	assign c_stateen = ctrl[21];
	assign c_srow0 = ctrl[20];
	assign c_srow1 = ctrl[19];
	assign c_srow2 = ctrl[18];
	assign c_isrow0 = ctrl[17];
	assign c_isrow1 = ctrl[16];
	assign c_mixcol = ctrl[15];
	assign c_loadkey = ctrl[14];
	assign c_keyen = ctrl[13];
	assign c_ke0 = ctrl[12];
	assign c_ke1 = ctrl[11];
	assign c_ke2 = ctrl[10];
	assign c_kxor = ctrl[9];
	assign c_ikxor = ctrl[6-:5];
	assign c_add = ctrl[8];
	assign c_sbox = ctrl[7];
	assign c_dec192_keysel = ctrl[1-:2];
	initial _sv2v_0 = 0;
endmodule